<?php
require_once __DIR__.'/../includes/auth.php'; require_role('admin');
if(($_GET['export']??'')==='csv'){$rows=$pdo->query("SELECT b.id,u.name student,e.name equipment,b.booking_date,b.start_time,b.end_time,b.quantity,b.status FROM bookings b JOIN users u ON u.id=b.student_user_id JOIN equipment e ON e.id=b.equipment_id ORDER BY b.booking_date DESC")->fetchAll();header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="booking-report.csv"');$out=fopen('php://output','w');fputcsv($out,array_keys($rows[0]??['No records']));foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;}
$count=$pdo->query("SELECT status,COUNT(*) total FROM bookings GROUP BY status")->fetchAll();page_header('Reports and Analytics','admin');?>
<div class="panel"><div class="d-flex justify-content-between align-items-center"><h2 class="section-title">Booking report</h2><a class="btn btn-primary" href="?export=csv">Download CSV</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($count as $r):?><tr><td><?=e($r['status'])?></td><td><?=$r['total']?></td></tr><?php endforeach?></tbody></table></div><p class="muted">Use the CSV export for spreadsheet analysis. PDF export can be added with a PDF library if required.</p></div><?php page_footer();?>
